from pathlib import Path
import re

ENGINE = Path("app/src/main/java/ro/alintudor/oracle/core/OracleGrowthEngine.kt")
text = ENGINE.read_text(encoding="utf-8")

anchor = '    private val keys=listOf("news","breakout","trend","momentum","volume","support_resistance","fundamentals","bollinger","ichimoku","market_sector","risk_reward","adx")\n'
helper = '''\n    private fun growthSector(ticker: String, seedSector: String?): String? {\n        return when (ticker.uppercase(Locale.US)) {\n            "CRWD", "PANW", "FTNT", "ZS", "OKTA", "S" -> "Cybersecurity"\n            "CRM", "NOW", "ORCL" -> "AI / Enterprise Software"\n            "VEEV" -> "Healthcare / Life Sciences Software"\n            "NVDA", "AMD", "AVGO", "MU", "QCOM", "MRVL", "ARM", "TSM", "ASML", "INTC", "SMCI", "LRCX", "AMAT", "KLAC", "WDC", "STX" -> "Semiconductors"\n            "LLY", "JNJ", "UNH", "MRK", "PFE", "ABBV", "BMY", "AMGN", "GILD", "REGN", "ISRG", "ABT", "TMO", "DHR", "SYK", "BSX", "MDT", "BDX", "EW", "ZBH", "RMD", "DXCM", "ALGN", "IDXX", "IQV", "HCA", "CI", "ELV", "HUM", "CVS", "MCK", "CAH", "COR" -> "Healthcare"\n            "SLB", "XOM", "CVX", "COP", "EOG", "OXY", "HAL", "MPC", "PSX", "VLO", "WMB", "KMI", "OKE", "LNG", "DVN", "FANG", "APA" -> "Energy"\n            "GE", "CAT", "CMI", "PCAR", "PH", "ROK", "EMR", "HON", "LHX", "RTX", "NOC", "GD", "TDG", "HEI", "TT", "CARR", "JCI", "IR", "PWR", "FIX", "MTZ", "EME", "BA", "LMT", "UPS", "FDX", "DAL", "UAL", "LUV", "AAL" -> "Industrials"\n            "NEE", "DUK", "SO", "AEP", "EXC", "SRE", "ED", "PEG", "WEC", "DTE", "FE", "ETR", "PPL", "AES", "CNP", "CMS", "NI" -> "Utilities"\n            else -> OracleRealData.resolvedSector(ticker, seedSector)\n        }\n    }\n\n    private fun growthCompany(ticker: String, seedCompany: String?): String {\n        if (!seedCompany.isNullOrBlank() && !seedCompany.equals(ticker, true)) return seedCompany\n        return when (ticker.uppercase(Locale.US)) {\n            "NVDA" -> "NVIDIA Corporation"\n            "VRT" -> "Vertiv Holdings Co."\n            "CEG" -> "Constellation Energy Corporation"\n            "AMD" -> "Advanced Micro Devices, Inc."\n            "AVGO" -> "Broadcom Inc."\n            "PLTR" -> "Palantir Technologies Inc."\n            "ANET" -> "Arista Networks, Inc."\n            "MU" -> "Micron Technology, Inc."\n            "AMZN" -> "Amazon.com, Inc."\n            "META" -> "Meta Platforms, Inc."\n            "MSFT" -> "Microsoft Corporation"\n            "GOOGL", "GOOG" -> "Alphabet Inc."\n            "AAPL" -> "Apple Inc."\n            "TSLA" -> "Tesla, Inc."\n            "NFLX" -> "Netflix, Inc."\n            "CRWD" -> "CrowdStrike Holdings, Inc."\n            "PANW" -> "Palo Alto Networks, Inc."\n            "NOW" -> "ServiceNow, Inc."\n            "ORCL" -> "Oracle Corporation"\n            "CRM" -> "Salesforce, Inc."\n            "ADBE" -> "Adobe Inc."\n            "SNOW" -> "Snowflake Inc."\n            "DDOG" -> "Datadog, Inc."\n            "NET" -> "Cloudflare, Inc."\n            "TSM" -> "Taiwan Semiconductor Manufacturing Company"\n            "ASML" -> "ASML Holding N.V."\n            "MELI" -> "MercadoLibre, Inc."\n            "SHOP" -> "Shopify Inc."\n            "COIN" -> "Coinbase Global, Inc."\n            "HOOD" -> "Robinhood Markets, Inc."\n            "UBER" -> "Uber Technologies, Inc."\n            "RKLB" -> "Rocket Lab USA, Inc."\n            "LUNR" -> "Intuitive Machines, Inc."\n            "ACN" -> "Accenture plc"\n            "IBM" -> "International Business Machines Corporation"\n            "CSCO" -> "Cisco Systems, Inc."\n            "INTU" -> "Intuit Inc."\n            "ADP" -> "Automatic Data Processing, Inc."\n            "ADSK" -> "Autodesk, Inc."\n            "CDNS" -> "Cadence Design Systems, Inc."\n            "SNPS" -> "Synopsys, Inc."\n            "FTNT" -> "Fortinet, Inc."\n            "ZS" -> "Zscaler, Inc."\n            "OKTA" -> "Okta, Inc."\n            "VEEV" -> "Veeva Systems Inc."\n            "SLB" -> "SLB"\n            else -> ticker.uppercase(Locale.US)\n        }\n    }\n'''
if helper.strip() not in text:
    if anchor not in text:
        raise SystemExit("Growth keys anchor not found")
    text = text.replace(anchor, anchor + helper, 1)

text, n1 = re.subn(r'val sector=byTicker\[c\.ticker\]\?\.sector', 'val sector=growthSector(c.ticker, byTicker[c.ticker]?.sector)', text)
text, n2 = re.subn(r'byTicker\[it\.ticker\]\?\.sector', 'growthSector(it.ticker, byTicker[it.ticker]?.sector)', text)
text, n3 = re.subn(r'val score=horizonScore\(pick\.components,h,byTicker\[pick\.ticker\]\?\.sector\)', 'val score=horizonScore(pick.components,h,growthSector(pick.ticker, byTicker[pick.ticker]?.sector))', text)
text, n4 = re.subn(r'val sector=meta\?\.sector', 'val sector=growthSector(pick.ticker, meta?.sector)', text)
text, n5 = re.subn(r'company=meta\?\.company\?:pick\.ticker', 'company=growthCompany(pick.ticker, meta?.company)', text)
text = text.replace('sector=sector?:"US"', 'sector=sector?:"Unknown"')

if not all(x > 0 for x in (n1, n2, n3, n4, n5)):
    raise SystemExit(f"Growth metadata anchors not fully found: {n1},{n2},{n3},{n4},{n5}")
ENGINE.write_text(text, encoding="utf-8")
print("Growth sector/company metadata patch applied")
